
using System;
using System.Collections.Generic;
using HealthcareInventoryManagementSystem.Domain.Enums;

namespace HealthcareInventoryManagementSystem.Domain.Entities
{
    public class PurchaseOrderEntity
    {
        public int PurchaseOrderId { get; set; }

        // Unique number generated by the backend.
        public string OrderNumber { get; set; } = string.Empty;

        // Supplier associated with this purchase order.
        public int SupplierId { get; set; }
        public Supplier Supplier { get; set; } = null!;

        public DateTime OrderDate { get; set; } = DateTime.UtcNow;

        public DateTime? ExpectedDeliveryDate { get; set; }

        // Every new purchase order starts as Draft.
        public PurchaseOrderStatus Status { get; set; }
            = PurchaseOrderStatus.Draft;

        // Financial totals calculated by the backend.
        public decimal Subtotal { get; set; }

        // Stores the tax percentage used to calculate the tax amount.
        public decimal TaxRate { get; set; }
        public decimal TaxAmount { get; set; }

        public decimal TotalAmount { get; set; }

        public string? Notes { get; set; }

        // Date when the purchase order was created.
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

        // Date when the purchase order was last updated.
        public DateTime? UpdatedAt { get; set; }

        // Date when the purchase order was approved.
        public DateTime? ApprovedAt { get; set; }

        // One purchase order can contain multiple items.
        public ICollection<PurchaseOrderItemEntity> Items { get; set; }
            = new List<PurchaseOrderItemEntity>();
    }
}
